import SwiftUI

@main struct MediaSFULiveAuctionApp: App { var body: some Scene { WindowGroup { AuctionRootView() } } }

@MainActor final class AuctionModel: ObservableObject {
    @Published var name = "Auctioneer"; @Published var grant = ""; @Published var role = "host"; @Published var auction: AuctionState?; @Published var token = ""; @Published var meetingId = ""; @Published var roomData: [String: Any] = [:]; @Published var busy = false; @Published var notice = ""; @Published var invites: [(String, String)] = []
    let api = AuctionAPI()
    var isHost: Bool { role == "host" }
    func enter() { busy = true; notice = ""; Task { do { let value: [String: Any]; if grant.isEmpty { value = try await api.create(hostName: name) } else { value = try await api.redeem(grant: grant, displayName: name); role = value["role"] as? String ?? "viewer"; meetingId = value["meetingId"] as? String ?? "" }; let auctionValue = value["auction"] as? [String: Any] ?? [:]; auction = AuctionState(auctionValue); token = (value[isHost ? "hostToken" : "participantToken"] as? String) ?? ""; roomData = value["data"] as? [String: Any] ?? [:]; if meetingId.isEmpty { meetingId = roomData["meetingID"] as? String ?? roomData["meetingId"] as? String ?? roomData["roomName"] as? String ?? "" } } catch { notice = error.localizedDescription }; busy = false } }
    func poll() { guard let auction, !token.isEmpty else { return }; Task { if let value = try? await api.snapshot(id: auction.id, token: token), let state = value["auction"] as? [String: Any] { self.auction = AuctionState(state) } } }
    func bid(_ increment: Int) { guard let auction, let lot = auction.openLot else { return }; busy = true; Task { do { let amount = max(lot.reserve, lot.highest + increment); let value = try await api.bid(id: auction.id, token: token, amountCents: amount); if let state = value["state"] as? [String: Any] { self.auction = AuctionState(state) } } catch { notice = error.localizedDescription }; busy = false } }
    func settle() { guard let auction else { return }; Task { do { let value = try await api.settle(id: auction.id, token: token); if let state = value["auction"] as? [String: Any] { self.auction = AuctionState(state) } } catch { notice = error.localizedDescription } } }
    func makeInvite(role: String) { guard let auction else { return }; Task { do { let grant = try await api.invite(id: auction.id, token: token, role: role); invites.append((role, "mediasfu-auction://join?invite=\(grant.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? grant)")) } catch { notice = error.localizedDescription } } }
    func end() { guard let auction else { return }; busy = true; Task { do { try await api.end(id: auction.id, token: token); self.auction = nil; token = ""; roomData = [:] } catch { notice = error.localizedDescription }; busy = false } }
}

private let auctionNavy = Color(red: 0.027, green: 0.051, blue: 0.11); private let auctionPanel = Color(red: 0.063, green: 0.106, blue: 0.165); private let auctionGold = Color(red: 1, green: 0.84, blue: 0.04); private let auctionTeal = Color(red: 0.21, green: 0.74, blue: 0.69)

struct AuctionRootView: View {
    @StateObject private var model = AuctionModel()
    var body: some View { Group { if model.auction == nil { AuctionEntryView(model: model) } else { AuctionRoomView(model: model) } }.preferredColorScheme(.dark).onOpenURL { url in if let grant = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems?.first(where: { $0.name == "invite" })?.value { model.grant = grant; model.name = "Bidder1" } } }
}
struct AuctionEntryView: View {
    @ObservedObject var model: AuctionModel
    var body: some View { VStack(alignment: .leading, spacing: 16) { Text("MEDIASFU SOLUTION STARTER").foregroundStyle(auctionGold).font(.caption.weight(.black)); Text(model.grant.isEmpty ? "Run a live auction" : "Enter the salesroom").font(.system(size: 40, weight: .black)); Text(model.grant.isEmpty ? "Premium native media, authoritative bids, and secure room creation." : "Your private invitation decides whether you can bid or watch.").foregroundStyle(.secondary); TextField("Display name", text: $model.name).textFieldStyle(.roundedBorder); Button(model.busy ? "Opening…" : model.grant.isEmpty ? "Open salesroom →" : "Enter auction →") { model.enter() }.buttonStyle(.borderedProminent).tint(auctionGold).foregroundStyle(.black); if !model.notice.isEmpty { Text(model.notice).foregroundStyle(.red) } }.padding(28).frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center).background(auctionNavy.ignoresSafeArea()) }
}
struct AuctionRoomView: View {
    @ObservedObject var model: AuctionModel
    @StateObject private var room = MediaSFURoomController()
    @State private var chat = ""
    private var mediaSFURoomName: String { model.roomData["roomName"] as? String ?? model.meetingId }
    private var roomApiToken: String { model.roomData["secret"] as? String ?? "" }
    private var roomLink: String { model.roomData["link"] as? String ?? "" }
    var body: some View { ZStack { MediaSFUNativeRoomView(controller: room, configuration: MediaSFURoomConfiguration(userName: model.name, roomName: mediaSFURoomName, roomApiToken: roomApiToken, roomLink: roomLink, eventType: "conference")).ignoresSafeArea(); ScrollView { VStack(alignment: .leading, spacing: 12) { HStack { VStack(alignment: .leading) { Text("◆ NORTHSTAR AUCTION HOUSE").foregroundStyle(auctionGold).font(.caption.weight(.black)); Text("MediaSFU native · \(model.role)").foregroundStyle(.secondary) }; Spacer(); Text(room.state).font(.caption); if model.isHost { Button("End", role: .destructive) { model.end() } } }.padding(14).background(auctionPanel).clipShape(RoundedRectangle(cornerRadius: 14)); if let lot = model.auction?.openLot { VStack(alignment: .leading, spacing: 8) { Text(lot.art).font(.system(size: 64)).frame(maxWidth: .infinity); Text("LOT \(lot.position + 1) · NOW BIDDING").foregroundStyle(auctionGold).font(.caption.weight(.black)); Text(lot.title).font(.title2.weight(.black)); Text(lot.displayPrice).foregroundStyle(auctionGold).font(.system(size: 34, weight: .black)); Text(lot.bidder.isEmpty ? "Reserve" : "\(lot.bidder) leads · \(lot.bids) bids").foregroundStyle(.secondary); if model.role == "bidder" { HStack { ForEach([2500, 10000, 50000], id: \.self) { increment in Button("Bid \(max(lot.reserve, lot.highest + increment) / 100)") { model.bid(increment) }.buttonStyle(.borderedProminent).tint(auctionGold).foregroundStyle(.black) } } }; if model.isHost { Button("🔨 Close lot and advance") { model.settle() }.buttonStyle(.borderedProminent).tint(auctionTeal) }; if model.role == "viewer" { Text("View-only invitation · bidding and publishing are disabled.").foregroundStyle(.secondary) } }.padding(18).background(auctionPanel).clipShape(RoundedRectangle(cornerRadius: 18)) }; HStack(spacing: 12) { Button { room.toggleAudio() } label: { Label("Mic", systemImage: "mic.fill") }; Button { room.toggleVideo() } label: { Label("Camera", systemImage: "video.fill") }; Button { room.toggleScreenShare() } label: { Label("Share", systemImage: "rectangle.inset.filled.and.person.filled") } }.buttonStyle(.bordered).disabled(model.role == "viewer"); AuctionPanel(model: model, chat: $chat); if model.isHost { VStack(alignment: .leading, spacing: 8) { Text("PRIVATE SINGLE-USE INVITES").foregroundStyle(auctionGold).font(.caption.weight(.black)); Text("Bidder links can bid and publish. Viewer links join read-only.").foregroundStyle(.secondary); HStack { Button("Bidder link") { model.makeInvite(role: "bidder") }; Button("Viewer link") { model.makeInvite(role: "viewer") } }.buttonStyle(.bordered); ForEach(Array(model.invites.enumerated()), id: \.offset) { _, invite in ShareLink(item: invite.1) { Text("Share \(invite.0) link") } } }.padding(16).background(auctionPanel).clipShape(RoundedRectangle(cornerRadius: 16)) }; if !model.notice.isEmpty { Text(model.notice).foregroundStyle(.red) } }.padding(14) }.background(.black.opacity(0.28)) }.task { while !Task.isCancelled { try? await Task.sleep(for: .seconds(1.5)); model.poll() } }.onDisappear { if model.isHost && model.auction != nil { model.end() } } }
}
private struct AuctionPanel: View { @ObservedObject var model: AuctionModel; @Binding var chat: String; var body: some View { VStack(alignment: .leading, spacing: 8) { Text("BIDDING FLOOR & SALESROOM CHAT").foregroundStyle(auctionGold).font(.caption.weight(.black)); Text("Every connected participant keeps an identity card. Use the Messages control in the MediaSFU room for live chat.").foregroundStyle(.secondary); HStack { TextField("Message the salesroom", text: $chat).textFieldStyle(.roundedBorder); Button("Open chat") { model.notice = "Open the Messages control in the MediaSFU room UI to send this message." }.disabled(model.role == "viewer") } }.padding(16).background(auctionPanel).clipShape(RoundedRectangle(cornerRadius: 16)) }
}
